arguments.command:
cat << 'PYEOF' | python3
import json

with open('/app/output/analysis_data.json') as f:
    d = json.load(f)

t = d['tournament']
k = d['kpis']

def make_chart_js(d):
    """Generate all Chart.js code blocks"""
    js = ''

    # Over-by-over scoring
    overs = d['over_scoring']
    js += f"""
new Chart(document.getElementById('chartOverScoring'), {{
  type: 'bar',
  data: {{
    labels: [{','.join([str(o) for o in range(20)])}],
    datasets: [
      {{
        label: 'Runs Per Over',
        data: [{','.join([str(o['rpo']) for o in overs])}],
        backgroundColor: 'rgba(79,195,247,0.6)',
        borderColor: '#4fc3f7',
        borderWidth: 1,
        yAxisID: 'y'
      }},
      {{
        label: 'Wickets',
        data: [{','.join([str(int(o['wickets'])) for o in overs])}],
        type: 'line',
        borderColor: '#ef5350',
        backgroundColor: 'rgba(239,83,80,0.1)',
        pointBackgroundColor: '#ef5350',
        yAxisID: 'y1',
        tension: 0.3
      }}
    ]
  }},
  options: {{
    responsive: true,
    interaction: {{ mode:'index', intersect:false }},
    scales: {{
      y: {{ title:{{display:true, text:'Runs Per Over'}}, beginAtZero:true }},
      y1: {{ position:'right', title:{{display:true, text:'Wickets'}}, beginAtZero:true, grid:{{drawOnChartArea:false}} }}
    }}
  }}
}});
"""

    # Top run scorers
    top_bats = d['top_batsmen'][:10]
    js += f"""
new Chart(document.getElementById('chartTopRuns'), {{
  type: 'bar',
  data: {{
    labels: [{','.join([f"'{b['striker']}'" for b in top_bats])}],
    datasets: [
      {{ label:'Runs', data: [{','.join([str(b['runs']) for b in top_bats])}], backgroundColor: {json.dumps(['#4fc3f7','#7c4dff','#66bb6a','#ffa726','#ef5350','#ab47bc','#ffee58','#26c6da','#ec407a','#8d6e63'])}, borderWidth:0 }}
    ]
  }},
  options: {{ indexAxis:'y', responsive:true, plugins:{{legend:{{display:false}}}}, scales:{{x:{{beginAtZero:true}}}} }}
}});
"""

    # SR vs Runs scatter
    top15 = d['top_batsmen'][:15]
    js += f"""
new Chart(document.getElementById('chartSRvsRuns'), {{
  type: 'scatter',
  data: {{
    datasets: [{{
      label: 'Batsmen',
      data: [{','.join([f"{{x:{b['runs']},y:{b['strike_rate']}}}" for b in top15])}],
      backgroundColor: 'rgba(79,195,247,0.7)',
      pointRadius: 7,
      pointHoverRadius: 10
    }}]
  }},
  options: {{
    responsive: true,
    plugins: {{
      tooltip: {{
        callbacks: {{
          label: function(ctx) {{
            return ctx.raw.x + ' runs, SR ' + ctx.raw.y;
          }}
        }}
      }}
    }},
    scales: {{
      x: {{ title:{{display:true, text:'Runs'}} }},
      y: {{ title:{{display:true, text:'Strike Rate'}} }}
    }}
  }}
}});
"""

    # Phase-wise runs
    ph_bat = d['phase_batting']
    js += f"""
new Chart(document.getElementById('chartPhaseRuns'), {{
  type: 'bar',
  data: {{
    labels: [{','.join([f"'{p['phase']}'" for p in ph_bat])}],
    datasets: [
      {{ label:'4s', data: [{','.join([str(p['fours']) for p in ph_bat])}], backgroundColor:'#4fc3f7' }},
      {{ label:'6s', data: [{','.join([str(p['sixes']) for p in ph_bat])}], backgroundColor:'#7c4dff' }},
      {{ label:'Other Runs', data: [{','.join([str(p['runs'] - p['fours']*4 - p['sixes']*6) for p in ph_bat])}], backgroundColor:'#66bb6a' }}
    ]
  }},
  options: {{ responsive:true, scales:{{x:{{stacked:true}},y:{{stacked:true,beginAtZero:true}}}} }}
}});

new Chart(document.getElementById('chartPhaseSR'), {{
  type: 'bar',
  data: {{
    labels: [{','.join([f"'{p['phase']}'" for p in ph_bat])}],
    datasets: [
      {{ label:'Strike Rate', data: [{','.join([str(p['sr']) for p in ph_bat])}], backgroundColor:['#7986cbcc','#81c784cc','#ef9a9acc'], borderWidth:0 }},
      {{ label:'Dot %', data: [{','.join([str(p['dot_pct']) for p in ph_bat])}], backgroundColor:['#7986cb44','#81c78444','#ef9a9a44'], borderWidth:0 }}
    ]
  }},
  options: {{ responsive:true }}
}});
"""

    # Batsman phase-wise
    bp_data = d['batsman_phase']
    batsmen_in_phase = {}
    for b in bp_data:
        name = b['striker']
        if name not in batsmen_in_phase:
            batsmen_in_phase[name] = {}
        batsmen_in_phase[name][b['phase']] = b['sr']
    sorted_batsmen = sorted(batsmen_in_phase.keys(), key=lambda x: sum(batsmen_in_phase[x].values()) if batsmen_in_phase[x] else 0, reverse=True)[:12]

    js += f"""
new Chart(document.getElementById('chartBatsmanPhase'), {{
  type: 'bar',
  data: {{
    labels: [{','.join([f"'{b}'" for b in sorted_batsmen])}],
    datasets: [
      {{ label:'Powerplay', data: [{','.join([str(batsmen_in_phase[b].get('Powerplay', 0)) for b in sorted_batsmen])}], backgroundColor:'#7986cb' }},
      {{ label:'Middle', data: [{','.join([str(batsmen_in_phase[b].get('Middle', 0)) for b in sorted_batsmen])}], backgroundColor:'#81c784' }},
      {{ label:'Death', data: [{','.join([str(batsmen_in_phase[b].get('Death', 0)) for b in sorted_batsmen])}], backgroundColor:'#ef9a9a' }}
    ]
  }},
  options: {{
    responsive: true,
    scales: {{ y: {{ beginAtZero:true, title:{{display:true, text:'Strike Rate'}} }} }}
  }}
}});
"""

    # Dismissal types
    dis_data = d['dismissals']
    js += f"""
new Chart(document.getElementById('chartDismissals'), {{
  type: 'doughnut',
  data: {{
    labels: [{','.join([f"'{di['wicket_type']}'" for di in dis_data])}],
    datasets: [{{ data: [{','.join([str(di['count']) for di in dis_data])}], backgroundColor:['#4fc3f7','#7c4dff','#66bb6a','#ffa726','#ef5350'] }}]
  }},
  options: {{ responsive:true, plugins:{{legend:{{position:'right'}}}} }}
}});
"""

    # Phase bowling economy
    ph_bowl = d['phase_bowling']
    js += f"""
new Chart(document.getElementById('chartPhaseBowlEcon'), {{
  type: 'bar',
  data: {{
    labels: [{','.join([f"'{p['phase']}'" for p in ph_bowl])}],
    datasets: [
      {{ label:'Economy Rate', data: [{','.join([str(p['economy']) for p in ph_bowl])}], backgroundColor:['#7986cb','#81c784','#ef9a9a'], borderWidth:0 }}
    ]
  }},
  options: {{ responsive:true, scales:{{y:{{beginAtZero:true,title:{{display:true,text:'Economy'}}}}}} }}
}});
"""

    # Bowler phase economy
    bowl_phase_data = d['bowler_phase']
    bowlers_in_phase = {}
    for b in bowl_phase_data:
        name = b['bowler']
        if name not in bowlers_in_phase:
            bowlers_in_phase[name] = {}
        bowlers_in_phase[name][b['phase']] = b['economy']
    sorted_bowlers = list(bowlers_in_phase.keys())[:10]

    js += f"""
new Chart(document.getElementById('chartBowlerPhase'), {{
  type: 'bar',
  data: {{
    labels: [{','.join([f"'{b}'" for b in sorted_bowlers])}],
    datasets: [
      {{ label:'Powerplay', data: [{','.join([str(bowlers_in_phase[b].get('Powerplay', 0)) for b in sorted_bowlers])}], backgroundColor:'#7986cb' }},
      {{ label:'Middle', data: [{','.join([str(bowlers_in_phase[b].get('Middle', 0)) for b in sorted_bowlers])}], backgroundColor:'#81c784' }},
      {{ label:'Death', data: [{','.join([str(bowlers_in_phase[b].get('Death', 0)) for b in sorted_bowlers])}], backgroundColor:'#ef9a9a' }}
    ]
  }},
  options: {{
    responsive: true,
    scales: {{ y: {{ beginAtZero:true, title:{{display:true, text:'Economy Rate'}} }} }}
  }}
}});
"""

    # Team batting
    team_bat = d['team_batting']
    js += f"""
new Chart(document.getElementById('chartTeamBatting'), {{
  type: 'bar',
  data: {{
    labels: [{','.join([f"'{b['batting_team']}'" for b in team_bat])}],
    datasets: [
      {{ label:'Avg Runs/Innings', data: [{','.join([str(b['avg_runs_per_innings']) for b in team_bat])}], backgroundColor:['#4fc3f7','#7c4dff','#66bb6a','#ffa726','#ef5350','#ab47bc','#ffee58','#26c6da','#ec407a','#8d6e63'], borderWidth:0 }}
    ]
  }},
  options: {{ responsive:true, plugins:{{legend:{{display:false}}}}, scales:{{y:{{beginAtZero:true}}}} }}
}});
"""

    # Team bowling
    team_bowl = d['team_bowling']
    js += f"""
new Chart(document.getElementById('chartTeamBowling'), {{
  type: 'bar',
  data: {{
    labels: [{','.join([f"'{b['bowling_team']}'" for b in team_bowl])}],
    datasets: [
      {{ label:'Economy', data: [{','.join([str(b['economy']) for b in team_bowl])}], backgroundColor:['#4fc3f7','#7c4dff','#66bb6a','#ffa726','#ef5350','#ab47bc','#ffee58','#26c6da','#ec407a','#8d6e63'], borderWidth:0 }}
    ]
  }},
  options: {{ responsive:true, plugins:{{legend:{{display:false}}}}, scales:{{y:{{beginAtZero:true}}}} }}
}});
"""

    # Team phase heatmap
    tp_data = d['team_phase']
    teams_in_tp = {}
    for t_item in tp_data:
        team = t_item['batting_team']
        if team not in teams_in_tp:
            teams_in_tp[team] = {}
        teams_in_tp[team][t_item['phase']] = t_item['sr']
    sorted_teams_tp = sorted(teams_in_tp.keys())

    js += f"""
new Chart(document.getElementById('chartTeamPhaseHeat'), {{
  type: 'bar',
  data: {{
    labels: [{','.join([f"'{t}'" for t in sorted_teams_tp])}],
    datasets: [
      {{ label:'Powerplay', data: [{','.join([str(teams_in_tp[t].get('Powerplay', 0)) for t in sorted_teams_tp])}], backgroundColor:'#7986cb' }},
      {{ label:'Middle', data: [{','.join([str(teams_in_tp[t].get('Middle', 0)) for t in sorted_teams_tp])}], backgroundColor:'#81c784' }},
      {{ label:'Death', data: [{','.join([str(teams_in_tp[t].get('Death', 0)) for t in sorted_teams_tp])}], backgroundColor:'#ef9a9a' }}
    ]
  }},
  options: {{
    responsive: true,
    scales: {{ y: {{ beginAtZero:true, title:{{display:true, text:'Strike Rate'}} }} }}
  }}
}});
"""

    # Extras by team
    ext_team = d['extras_by_team']
    js += f"""
new Chart(document.getElementById('chartExtrasTeam'), {{
  type: 'bar',
  data: {{
    labels: [{','.join([f"'{b['bowling_team']}'" for b in ext_team])}],
    datasets: [
      {{ label:'Wides', data: [{','.join([str(b['wides']) for b in ext_team])}], backgroundColor:'#ef5350' }},
      {{ label:'No-Balls', data: [{','.join([str(b['noballs']) for b in ext_team])}], backgroundColor:'#ffa726' }},
      {{ label:'Byes', data: [{','.join([str(b['byes']) for b in ext_team])}], backgroundColor:'#4fc3f7' }},
      {{ label:'Leg-Byes', data: [{','.join([str(b['legbyes']) for b in ext_team])}], backgroundColor:'#66bb6a' }}
    ]
  }},
  options: {{ responsive:true, scales:{{x:{{stacked:true}},y:{{stacked:true,beginAtZero:true}}}} }}
}});
"""

    # Extras type pie
    total_wides = sum(b['wides'] for b in ext_team)
    total_noballs = sum(b['noballs'] for b in ext_team)
    total_byes = sum(b['byes'] for b in ext_team)
    total_legbyes = sum(b['legbyes'] for b in ext_team)
    js += f"""
new Chart(document.getElementById('chartExtrasType'), {{
  type: 'pie',
  data: {{
    labels: ['Wides','No-Balls','Byes','Leg-Byes'],
    datasets: [{{ data: [{total_wides},{total_noballs},{total_byes},{total_legbyes}], backgroundColor:['#ef5350','#ffa726','#4fc3f7','#66bb6a'] }}]
  }},
  options: {{ responsive:true, plugins:{{legend:{{position:'right'}}}} }}
}});
"""

    # Venue innings comparison
    vi_data = d['venue_innings']
    venues_in_vi = []
    for v in vi_data:
        short = v['venue'].split(',')[0]
        if short not in venues_in_vi:
            venues_in_vi.append(short)

    inn1_avgs = []
    inn2_avgs = []
    for v in venues_in_vi:
        found1 = found2 = 0
        for vi in vi_data:
            short = vi['venue'].split(',')[0]
            if short == v:
                if vi['innings'] == 1:
                    found1 = vi['avg']
                else:
                    found2 = vi['avg']
        inn1_avgs.append(found1)
        inn2_avgs.append(found2)

    js += f"""
new Chart(document.getElementById('chartVenueInnings'), {{
  type: 'bar',
  data: {{
    labels: [{','.join([f"'{v}'" for v in venues_in_vi])}],
    datasets: [
      {{ label:'1st Innings', data: [{','.join([str(a) for a in inn1_avgs])}], backgroundColor:'#4fc3f7' }},
      {{ label:'2nd Innings', data: [{','.join([str(a) for a in inn2_avgs])}], backgroundColor:'#7c4dff' }}
    ]
  }},
  options: {{ responsive:true, scales:{{y:{{beginAtZero:true,title:{{display:true,text:'Average Score'}}}}}} }}
}});
"""

    # Venue avg runs
    vs_data = d['venue_stats']
    js += f"""
new Chart(document.getElementById('chartVenueAvg'), {{
  type: 'bar',
  data: {{
    labels: [{','.join([f"'{v['venue'].split(',')[0]}'" for v in vs_data])}],
    datasets: [
      {{ label:'Avg Runs/Match', data: [{','.join([str(v['avg_runs_per_match']) for v in vs_data])}], backgroundColor:['#4fc3f7','#7c4dff','#66bb6a','#ffa726','#ef5350','#ab47bc','#ffee58','#26c6da','#ec407a','#8d6e63'], borderWidth:0 }}
    ]
  }},
  options: {{ indexAxis:'y', responsive:true, plugins:{{legend:{{display:false}}}}, scales:{{x:{{beginAtZero:true}}}} }}
}});

new Chart(document.getElementById('chartVenueRPO'), {{
  type: 'bar',
  data: {{
    labels: [{','.join([f"'{v['venue'].split(',')[0]}'" for v in vs_data])}],
    datasets: [
      {{ label:'Runs/Over', data: [{','.join([str(v['runs_per_over']) for v in vs_data])}], backgroundColor:['#4fc3f7','#7c4dff','#66bb6a','#ffa726','#ef5350','#ab47bc','#ffee58','#26c6da','#ec407a','#8d6e63'], borderWidth:0 }}
    ]
  }},
  options: {{ indexAxis:'y', responsive:true, plugins:{{legend:{{display:false}}}}, scales:{{x:{{beginAtZero:true}}}} }}
}});
"""

    return js

# Build HTML
html_parts = []
html_parts.append(f'''<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>IPL 2026 Ball-by-Ball Analytics Report</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.7/dist/chart.umd.min.js"></script>
<style>
  :root {{
    --bg: #0f1117;
    --surface: #1a1d29;
    --surface2: #242736;
    --border: #2e3245;
    --text: #e8eaed;
    --text2: #9aa0b4;
    --accent: #4fc3f7;
    --accent2: #7c4dff;
    --green: #66bb6a;
    --red: #ef5350;
    --orange: #ffa726;
    --yellow: #ffee58;
    --purple: #ab47bc;
  }}
  * {{ margin:0; padding:0; box-sizing:border-box; }}
  body {{ background: var(--bg); color: var(--text); font-family: 'Segoe UI', system-ui, -apple-system, sans-serif; line-height:1.6; }}
  .container {{ max-width:1280px; margin:0 auto; padding:24px; }}
  h1 {{ font-size:2.2rem; font-weight:800; margin-bottom:4px; background: linear-gradient(135deg, #4fc3f7 0%, #7c4dff 100%); -webkit-background-clip:text; -webkit-text-fill-color:transparent; }}
  .subtitle {{ color: var(--text2); font-size:1rem; margin-bottom:32px; }}
  h2 {{ font-size:1.5rem; font-weight:700; margin:48px 0 20px; padding-bottom:10px; border-bottom:2px solid var(--border); color: var(--accent); }}
  h3 {{ font-size:1.15rem; font-weight:600; margin:28px 0 14px; color: var(--text); }}
  .kpi-grid {{ display:grid; grid-template-columns:repeat(5,1fr); gap:16px; margin:24px 0 40px; }}
  .kpi-card {{ background:var(--surface); border:1px solid var(--border); border-radius:12px; padding:20px 16px; text-align:center; position:relative; overflow:hidden; }}
